// Compare: the same message and the same recorded voice, generated by two or three models, one after another, through the SAME pipeline as Create
// (window.pg.run → app.js runGeneration → the model adapters; background preloads, residency and eviction apply). Every number shown is taken from
// that run's own result. Blind mode hides model identities (and the metrics that would give them away) until the listener reveals them.
import * as player from './player.js';
import * as store from './history.js';
import {ranOn, settingsText} from './models-info.js';

const $ = (s, el = document) => el.querySelector(s);
const pg = () => window.pg, ux = () => window.ux, S = () => window.pg.state;
const esc = (t) => String(t).replace(/[&<>"]/g, (c) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));
const secs = (ms) => ms == null ? '—' : (ms / 1000).toFixed(ms < 10000 ? 2 : 1) + ' s';
const LANG = {en: 'English', zh: 'Mandarin', mixed: 'Mandarin + English', unknown: '—'};
const C = {text: null, refText: null, picked: new Set(), userPicked: false, blind: false, accepted: false, session: null, stopAfter: false, log: [], root: null};

// ---- compatibility: what each model can honestly be asked to do with this message --------------------------------------------------
// ok = supported; experimental = runs, but quality for this case has not been verified; no = not supported (never sent to the model).
function compat(id, lang) {
  const why = window.pg?.state.unavailable?.[id]; if (why) return {level: 'no', why: 'Not available on this device: ' + why};
  if (lang === 'unknown') return {level: 'no', why: 'Type a message first.'};
  if (id === 'chatterbox') return lang === 'en' ? {level: 'ok', why: 'English'} : {level: 'no', why: 'English only — this message contains Mandarin.'};
  if (lang === 'mixed') return {level: 'experimental', why: id === 'f5' ? 'Mixed sentences are experimental: English words inside Mandarin are often mispronounced.' : 'Mixed sentences work, but English words inside Mandarin can be misheard. Not verified by listening.'};
  return {level: 'ok', why: LANG[lang]};
}
const inputs = () => {
  const text = C.text ?? window.document.getElementById('text').value, refText = C.refText ?? window.document.getElementById('refText').value;
  const lang = ux().detectLang(text.trim()), rec = S().recording, recLang = ux().recordedLang;
  return {text, refText, lang, ref: S().ref, rec, recLang};
};
function refNote(lang, recLang) {   // the same rule as Create's scene 3: a recording in another language is allowed only as an explicit choice
  if (!recLang || lang === 'unknown') return null;
  if (lang === 'mixed') return {kind: 'info', text: 'Your message mixes Mandarin and English. How well your voice carries across languages is experimental.'};
  if (lang !== recLang) return {kind: 'warn', text: `Your message is ${LANG[lang]} but your recording is ${LANG[recLang]}. Cross-language voice cloning is experimental and may sound less like you — record again in ${LANG[lang]} in Create for the best match.`};
  return {kind: 'ok', text: `Your message and your recording are both ${LANG[lang]}.`};
}

// ---- inputs panel ------------------------------------------------------------------------------------------------------------------
// The message editor is rendered once per prefill (renderMsg) and never replaced while typing, so IME composition (Zhuyin, Pinyin) is never interrupted;
// everything that depends on it (language, compatible models, warnings, the button) lives in #cmpRest and is re-rendered freely.
function renderMsg() {
  const r = C.root, I = inputs();
  r.querySelector('#cmpMsg').innerHTML = `<label for="cmpText">Message</label><textarea id="cmpText" rows="2" spellcheck="false" placeholder="Type a sentence…">${esc(I.text)}</textarea>`;
  const t = $('#cmpText', r);
  t.addEventListener('input', (e) => { C.text = t.value; C.accepted = false; if (!e.isComposing) { clearTimeout(renderMsg.t); renderMsg.t = setTimeout(render, 250); } });
  t.addEventListener('compositionend', () => { clearTimeout(renderMsg.t); renderMsg.t = setTimeout(render, 250); });
}
function render() {
  const r = C.root; if (!r) return;
  const I = inputs(), note = refNote(I.lang, I.recLang), tiles = pg().tiles, hasRef = !!I.ref;
  for (const id of [...C.picked]) if (compat(id, I.lang).level === 'no') C.picked.delete(id);
  if (!C.userPicked && I.lang !== 'unknown') tiles.forEach((m) => { if (compat(m.id, I.lang).level === 'ok') C.picked.add(m.id); });
  const needTranscript = [...C.picked].some((id) => pg().models.find((m) => m.id === id)?.needsRefText) && !I.refText.trim();
  const mismatch = note?.kind === 'warn';
  const blockers = [!I.text.trim() && 'Type a message.', !hasRef && 'Record your voice in Create first (no default voice is used).', C.picked.size < 2 && 'Choose at least two models.',
    needTranscript && 'ZipVoice and F5-TTS need the exact words of your recording.', mismatch && !C.accepted && 'Confirm the recording language below.', pg().busy && 'Another generation is running.'].filter(Boolean);
  r.querySelector('#cmpRest').innerHTML = `
    <div class="cmp-field"><div class="cmp-under"><span class="chip-lang">${I.text.trim() ? 'Detected: ' + LANG[I.lang] : ''}</span>${C.text != null ? '<button type="button" class="text-btn" id="cmpUseCreate">Use the message from Create</button>' : '<span class="fine">Same as in Create. Editing it here does not change Create.</span>'}</div></div>
    <div class="cmp-field"><span class="lbl">Your voice</span>
      ${hasRef ? `<p class="cmp-voice">Your recording · ${I.rec ? I.rec.sec.toFixed(1) : (I.ref.samples.length / I.ref.sampleRate).toFixed(1)} s${I.recLang ? ' · ' + LANG[I.recLang] + ' passage' : ''} <button type="button" class="text-btn" id="cmpRerecord">Record again in Create</button></p>
        <details class="cmp-tr"${needTranscript ? ' open' : ''}><summary>Words in your recording <span class="fine">(used by ZipVoice and F5-TTS)</span></summary><input type="text" id="cmpRefText" value="${esc(I.refText)}" aria-label="Exact words of your recording">${C.refText != null ? '<button type="button" class="text-btn" id="cmpUseCreateTr">Use the words from Create</button>' : ''}</details>`
      : `<p class="cmp-voice warn">No recording yet. <button type="button" class="text-btn" id="cmpRecord">Record your voice in Create</button></p>`}
      ${note ? `<p class="lang-hint" data-kind="${note.kind}">${note.text}</p>` : ''}
      ${mismatch ? `<label class="check"><input type="checkbox" id="cmpAccept"${C.accepted ? ' checked' : ''}> Use this recording anyway</label>` : ''}</div>
    <fieldset class="cmp-models"><legend>Models</legend>${tiles.map((m) => { const c = compat(m.id, I.lang), on = C.picked.has(m.id);
      return `<div class="cmp-model" data-level="${c.level}"><label><input type="checkbox" data-pick="${m.id}"${on ? ' checked' : ''}${c.level === 'no' ? ' disabled' : ''}> <b>${pg().tileName(m)}</b></label>
        <span class="cmp-why">${c.level === 'experimental' ? '<em class="exp">Experimental</em> ' : ''}${c.level === 'ok' ? 'Supported' : esc(c.why)}</span>
        ${c.level !== 'no' ? `<details class="cmp-set"><summary>Settings: ${esc(summary(m))}</summary><div class="params" data-params="${m.id}"></div>${m.fallback ? '<p class="fine">Backend follows Advanced settings → ZipVoice backend.</p>' : ''}</details>` : ''}</div>`; }).join('')}</fieldset>
    <div class="cmp-go">
      <label class="switch"><input type="checkbox" id="cmpBlind"${C.blind ? ' checked' : ''}> <span>Blind listening</span><small>Hide the model names until you have listened and picked a favourite.</small></label>
      <div class="cmp-run"><button type="button" class="cta" id="cmpRun"${blockers.length || C.session?.running ? ' disabled' : ''}><span class="cta-fill" aria-hidden="true"></span><span class="cta-label">${C.session?.running ? 'Comparing…' : `Compare ${C.picked.size || ''} models`.replace('  ', ' ')}</span></button>
      ${C.session?.running ? '<button type="button" class="pill-btn" id="cmpStop">Stop after this model</button>' : ''}</div>
      <p class="soft-warn" id="cmpNeed">${C.session?.running ? '' : blockers.join(' ')}</p></div>`;
  for (const m of tiles) { const host = r.querySelector(`[data-params="${m.id}"]`); if (!host) continue; const pre = `cmp-${m.id}-`; host.innerHTML = pg().paramControls(m, pre); pg().bindParamControls(m, host, pre);
    host.addEventListener('input', (e) => { const el = e.target.closest('[data-param]'); if (el) { pg().setParams(m.id, {[el.dataset.param]: el.value}); host.closest('details').querySelector('summary').textContent = 'Settings: ' + summary(m); } });
    host.querySelectorAll('button.preset').forEach((b) => b.addEventListener('click', () => { pg().setParams(m.id, {[b.dataset.p]: b.dataset.v}); host.closest('details').querySelector('summary').textContent = 'Settings: ' + summary(m); })); }
  bind();
}
const summary = (m) => settingsText(m, pg().paramValues(m));   // one line of the model's current settings, from the shared per-model store
function bind() {
  const r = C.root;
  $('#cmpUseCreate', r)?.addEventListener('click', () => { C.text = null; C.accepted = false; renderMsg(); render(); });
  $('#cmpRefText', r)?.addEventListener('input', (e) => { C.refText = e.target.value; });
  $('#cmpRefText', r)?.addEventListener('change', () => render());
  $('#cmpUseCreateTr', r)?.addEventListener('click', () => { C.refText = null; render(); });
  for (const id of ['cmpRerecord', 'cmpRecord']) $('#' + id, r)?.addEventListener('click', () => ux().go(ux().chosen && document.getElementById('text').value.trim() ? 'voice' : 'model'));
  $('#cmpAccept', r)?.addEventListener('change', (e) => { C.accepted = e.target.checked; render(); });
  r.querySelectorAll('[data-pick]').forEach((b) => b.addEventListener('change', () => { C.userPicked = true; b.checked ? C.picked.add(b.dataset.pick) : C.picked.delete(b.dataset.pick); render(); }));
  $('#cmpBlind', r).addEventListener('change', (e) => { C.blind = e.target.checked; render(); });
  $('#cmpRun', r).addEventListener('click', run);
  $('#cmpStop', r)?.addEventListener('click', () => { C.stopAfter = true; $('#cmpStop', r).disabled = true; $('#cmpStop', r).textContent = 'Stopping after this model…'; });
}

// ---- run ----------------------------------------------------------------------------------------------------------------------------
const shuffle = (a) => { const r = new Uint32Array(a.length); crypto.getRandomValues(r); return a.map((x, i) => [r[i], x]).sort((p, q) => p[0] - q[0]).map((p) => p[1]); };
async function run() {
  const I = inputs(); if (C.session?.running) return;
  const order = pg().tiles.filter((m) => C.picked.has(m.id)).map((m) => m.id);
  if (S().paramsShownFor) pg().readParams(S().paramsShownFor);   // settings typed in Advanced for Create's model, even if no input event fired
  const letters = shuffle(order.map((_, i) => 'ABC'[i]));
  const ses = C.session = {id: crypto.randomUUID(), t0: performance.now(), when: new Date(), running: true, text: I.text.trim(), lang: I.lang, refSec: I.ref.samples.length / I.ref.sampleRate, recLang: I.recLang, refText: I.refText.trim(),
    order, blind: C.blind, labels: Object.fromEntries(order.map((id, i) => [id, letters[i]])), revealed: !C.blind, choice: null, ratings: {}, res: Object.fromEntries(order.map((id) => [id, {status: 'waiting', stage: ''}])),
    params: {}, loadBefore: {}, env: env()};
  C.stopAfter = false;
  store.list().filter((e) => e.compareId && e.hidden).forEach((e) => store.update(e.id, {hidden: false}));   // an earlier unrevealed blind run becomes visible
  render(); renderResults(); document.getElementById('cmpResults').scrollIntoView({block: 'start', behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth'});
  for (const id of order) {
    const res = ses.res[id], tile = pg().models.find((m) => m.id === id);
    if (C.stopAfter) { res.status = 'skipped'; continue; }
    const routed = pg().routeModel(tile); ses.loadBefore[id] = S().resident.has(routed) ? 'loaded' : S().loading.has(routed) ? 'loading in the background' : 'not loaded';
    ses.params[id] = pg().paramValues(tile);
    res.status = 'running'; res.stage = ses.loadBefore[id] === 'loaded' ? 'Generating…' : 'Preparing the model…'; res.t0 = performance.now(); renderResults();
    try {
      const out = await pg().run({tile, text: ses.text, ref: S().ref, refText: ses.refText, refName: S().refName, params: ses.params[id], source: 'compare',
        extra: {compareId: ses.id, blindLabel: ses.blind ? ses.labels[id] : null, hidden: ses.blind},
        onProgress: ({text}) => { if (text) { res.stage = text; paintStage(id); } }, onNotice: (n) => { res.notice = n; }});
      res.run = out.run; res.entryId = out.run.entryId; res.waitMs = performance.now() - ses.t0; res.status = 'done';
    } catch (e) { res.status = 'failed'; res.error = String(e.message || e).split('\n')[0]; res.released = !!e.released; }
    renderResults();
  }
  ses.running = false; ses.totalMs = performance.now() - ses.t0; C.stopAfter = false;
  window.lastCompare = summaryOf(ses);   // read-only hook for the regression script
  render(); renderResults();
}
function env() {
  const ua = navigator.userAgentData?.brands?.find((b) => /Chrome|Edge/.test(b.brand)), m = navigator.userAgent.match(/Chrome\/([\d.]+)/);
  return {browser: ua ? `${ua.brand} ${m ? m[1] : ua.version}` : navigator.userAgent.split(' ').slice(-2).join(' '), webgpu: !!navigator.gpu, cores: navigator.hardwareConcurrency || null, memoryGB: navigator.deviceMemory || null, adapter: S().gpuAdapter || null};
}
const summaryOf = (ses) => ({id: ses.id, order: ses.order, blind: ses.blind, labels: ses.labels, revealed: ses.revealed, lang: ses.lang, loadBefore: ses.loadBefore,
  results: Object.fromEntries(Object.entries(ses.res).map(([id, r]) => [id, {status: r.status, error: r.error || null, entryId: r.entryId || null, waitMs: r.waitMs ?? null,
    run: r.run && {model: r.run.model, backendUsed: r.run.backendUsed, genMs: r.run.genMs, audioSec: r.run.audioSec, rtf: r.run.rtf, clickToResultMs: r.run.clickToResultMs, loadThisClickMs: r.run.loadThisClickMs, modelReused: r.run.modelReused, params: r.run.params, text: r.run.text}}]))});

// ---- results ------------------------------------------------------------------------------------------------------------------------
const name = (ses, id) => ses.blind && !ses.revealed ? `Sample ${ses.labels[id]}` : pg().tileName(pg().models.find((m) => m.id === id));
const loadText = (r) => r.modelReused ? 'Already loaded — no waiting' : r.preloadedInBackground ? `Was still loading in the background: waited ${secs(r.loadThisClickMs)}` : `Loaded for this comparison: ${secs(r.loadThisClickMs)}`;
function paintStage(id) { const el = document.querySelector(`[data-cmp="${id}"] .cmp-stage`); if (el && C.session) el.textContent = stageLine(C.session, id); }
function stageLine(ses, id) {
  const r = ses.res[id];
  if (r.status === 'waiting') return ses.blind && !ses.revealed ? 'Waiting' : 'Waiting for its turn';
  if (r.status === 'running') return /^Generating…/.test(r.stage) ? 'Generating…' : r.stage;   // runtime stages only (F5 steps, Chatterbox encoding, model preparation)
  if (r.status === 'skipped') return 'Skipped (stopped)';
  if (r.status === 'failed') return 'Failed: ' + r.error + (r.released ? ' — the model was released and will reload next time' : '');
  return '';
}
function renderResults() {
  const host = document.getElementById('cmpResults'), ses = C.session; if (!host) return;
  host.querySelectorAll('[data-cmp]').forEach((el) => player.unmount('cmp:' + el.dataset.cmp));
  if (!ses) { host.innerHTML = ''; return; }
  const blindHold = ses.blind && ses.running;   // in blind mode nothing is shown until every sample exists, so the order of arrival gives nothing away
  const ids = ses.blind ? [...ses.order].sort((a, b) => ses.labels[a].localeCompare(ses.labels[b])) : ses.order;
  const done = ses.order.filter((id) => ses.res[id].status === 'done');
  host.innerHTML = `<div class="cmp-head"><h2>${ses.running ? (blindHold ? `Generating sample ${ses.order.findIndex((id) => ses.res[id].status === 'running') + 1} of ${ses.order.length}…` : 'Comparing…') : 'Results'}</h2>
      ${!ses.running ? `<div class="cmp-actions"><button type="button" class="pill-btn" id="cmpAgain">Compare again</button><button type="button" class="text-btn" id="cmpEdit">Change message or voice</button></div>` : ''}</div>
    ${blindHold ? '<p class="fine">Blind listening: the samples appear together when all of them are ready.</p>' : `<div class="cmp-grid" data-n="${ids.length}">${ids.map((id) => card(ses, id)).join('')}</div>`}
    ${!ses.running && ses.blind && done.length ? blindPanel(ses, done) : ''}
    ${!ses.running ? conditions(ses) : ''}${C.log.length ? blindLog() : ''}`;
  for (const id of ids) {
    const r = ses.res[id], slot = host.querySelector(`[data-cmp="${id}"] .cmp-player`), e = r.entryId && store.get(r.entryId);
    if (slot && e) player.mount(slot, {key: 'cmp:' + id, label: name(ses, id), pk: e.peaks, sec: e.audioSec, getUrl: () => store.url(e)});
    else if (slot && r.status === 'done') slot.innerHTML = '<p class="fine">This result was deleted in My creations.</p>';
  }
  $('#cmpAgain', host)?.addEventListener('click', run);
  $('#cmpEdit', host)?.addEventListener('click', () => { C.root.querySelector('#cmpText')?.focus(); C.root.scrollIntoView({block: 'start'}); });
  host.querySelectorAll('[data-dl]').forEach((a) => a.addEventListener('click', () => { const e = store.get(a.dataset.dl); if (e) a.href = store.url(e); }));
  host.querySelectorAll('[name="cmpPick"]').forEach((b) => b.addEventListener('change', () => { ses.choice = b.value; }));
  host.querySelectorAll('[data-rate]').forEach((s) => s.addEventListener('change', () => { const [id, k] = s.dataset.rate.split(':'); (ses.ratings[id] ??= {})[k] = s.value ? +s.value : null; }));
  $('#cmpReveal', host)?.addEventListener('click', () => reveal(ses));
}
function card(ses, id) {
  const r = ses.res[id], run = r.run, showId = !ses.blind || ses.revealed, e = r.entryId && store.get(r.entryId);
  const tile = pg().models.find((m) => m.id === id);
  return `<article class="cmp-card" data-cmp="${id}" data-status="${r.status}" aria-label="${esc(name(ses, id))}">
    <header><h3>${esc(name(ses, id))}</h3>${showId && run ? `<span class="badge">${/WebGPU/.test(run.backendUsed) ? 'GPU' : 'CPU'}</span>` : ''}${ses.blind && ses.revealed ? `<span class="fine">was Sample ${ses.labels[id]}</span>` : ''}</header>
    <p class="cmp-stage" aria-live="polite">${esc(stageLine(ses, id))}</p>
    ${r.notice && showId ? `<p class="soft-warn">${esc(r.notice)}</p>` : ''}
    ${r.status === 'done' ? `<div class="cmp-player"></div>
      <div class="cmp-links">${e ? `<a class="text-btn" data-dl="${e.id}" download="${esc((showId ? pg().tileName(tile) : 'sample-' + ses.labels[id]).replace(/\W+/g, '-').toLowerCase())}.wav" href="#">Download WAV</a>` : ''}</div>
      ${showId ? `<dl class="metrics">
        <div><dt>Ran on</dt><dd title="${esc(run.backendUsed)}">${esc(ranOn(run.backendUsed))}</dd></div>
        <div><dt>Speech length</dt><dd>${run.audioSec.toFixed(2)} s</dd></div>
        <div><dt>Generation time</dt><dd>${secs(run.genMs)}</dd></div>
        <div><dt title="Real-time factor: seconds of work per second of speech. Below 1 is faster than real time (but still not streaming).">RTF</dt><dd>${run.rtf.toFixed(2)}</dd></div>
        <div><dt>Model loading</dt><dd>${loadText(run)}</dd></div>
        <div><dt>Its turn → audio</dt><dd>${secs(run.clickToResultMs)}</dd></div>
        <div><dt>You waited (since Compare)</dt><dd>${secs(r.waitMs)}</dd></div>
        <div><dt>Settings</dt><dd>${esc(settingsText(tile, run.params))}</dd></div>
        ${run.detail?.ortRuntime ? `<div><dt>Runtime</dt><dd>ONNX Runtime ${esc(run.detail.ortRuntime === 'patched' ? 'fast-start build' : run.detail.ortRuntime)}</dd></div>` : ''}
      </dl>` : ''}` : ''}</article>`;
}
function blindPanel(ses, done) {
  const ids = [...done].sort((a, b) => ses.labels[a].localeCompare(ses.labels[b])), opt = (id, k) => `<select data-rate="${id}:${k}" aria-label="${k === 'nat' ? 'How natural' : 'How much like you'} — Sample ${ses.labels[id]}"${ses.revealed ? ' disabled' : ''}><option value="">—</option>${[1, 2, 3, 4, 5].map((v) => `<option${ses.ratings[id]?.[k] === v ? ' selected' : ''}>${v}</option>`).join('')}</select>`;
  return `<section class="blind" aria-labelledby="blindTitle"><h3 id="blindTitle">${ses.revealed ? 'Your listening notes' : 'Which one do you prefer?'}</h3>
    <p class="fine">Listen to each sample, then pick your favourite. Ratings are optional (1 = poor, 5 = excellent). These are your personal impressions from one sentence, kept in this tab — not a scientific score.</p>
    <table class="blind-t"><thead><tr><th>Sample</th><th>Favourite</th><th>Sounds natural</th><th>Sounds like me</th>${ses.revealed ? '<th>Model</th>' : ''}</tr></thead><tbody>
    ${ids.map((id) => `<tr><td>Sample ${ses.labels[id]}</td><td><input type="radio" name="cmpPick" value="${id}" aria-label="Prefer Sample ${ses.labels[id]}"${ses.choice === id ? ' checked' : ''}${ses.revealed ? ' disabled' : ''}></td><td>${opt(id, 'nat')}</td><td>${opt(id, 'sim')}</td>${ses.revealed ? `<td>${esc(pg().tileName(pg().models.find((m) => m.id === id)))}</td>` : ''}</tr>`).join('')}</tbody></table>
    ${ses.revealed ? '' : '<button type="button" class="pill-btn" id="cmpReveal">Reveal the models</button>'}</section>`;
}
function reveal(ses) {
  ses.revealed = true;
  Object.values(ses.res).forEach((r) => r.entryId && store.update(r.entryId, {hidden: false}));
  C.log.push({when: ses.when, text: ses.text, lang: ses.lang, labels: ses.labels, choice: ses.choice, ratings: JSON.parse(JSON.stringify(ses.ratings)), models: ses.order.filter((id) => ses.res[id].status === 'done')});
  window.lastCompare = summaryOf(ses); window.blindLog = C.log;
  renderResults();
}
function blindLog() {   // all blind rounds of this session, with simple counts — no averages pretending to be a MOS
  const tally = {}; C.log.forEach((b) => { if (b.choice) tally[b.choice] = (tally[b.choice] || 0) + 1; });
  return `<section class="blind-log"><h3>Blind rounds this session</h3><p class="fine">${C.log.length} round${C.log.length > 1 ? 's' : ''}. Favourite chosen: ${Object.entries(tally).map(([id, n]) => `${esc(pg().tileName(pg().models.find((m) => m.id === id)))} ${n}×`).join(', ') || 'none picked'}. Personal preferences from a few sentences; they do not rank the models.</p>
    <table><thead><tr><th>Message</th><th>Favourite</th><th>Ratings (natural / like me)</th></tr></thead><tbody>${C.log.map((b) => `<tr><td>${esc(b.text.length > 48 ? b.text.slice(0, 47) + '…' : b.text)}</td><td>${b.choice ? esc(pg().tileName(pg().models.find((m) => m.id === b.choice))) : '—'}</td><td>${b.models.map((id) => `${esc(pg().tileName(pg().models.find((m) => m.id === id)).split('-')[0])} ${b.ratings[id]?.nat ?? '–'}/${b.ratings[id]?.sim ?? '–'}`).join(' · ')}</td></tr>`).join('')}</tbody></table></section>`;
}
function conditions(ses) {   // what makes this comparison meaningful (or not), recorded for every run
  const showId = !ses.blind || ses.revealed;
  return `<details class="conditions"><summary>How this comparison was run</summary><ul>
    <li><b>Same input for every model:</b> the same ${ses.text.length}-character ${LANG[ses.lang]} message and the same ${ses.refSec.toFixed(1)} s recording${ses.recLang ? ' (' + LANG[ses.recLang] + ' passage)' : ''}${ses.order.some((id) => pg().models.find((m) => m.id === id).needsRefText) ? ' with its transcript for ZipVoice and F5-TTS (Chatterbox does not use one)' : ''}.</li>
    <li><b>Different models:</b> different architectures, each with its own settings (below); they are not tuned to match each other.</li>
    <li><b>One after another:</b> ${showId ? ses.order.map((id) => pg().tileName(pg().models.find((m) => m.id === id))).join(' → ') : 'one at a time'}, never in parallel, so they do not compete for the GPU.${showId ? ' Model state before its turn: ' + ses.order.map((id) => `${pg().tileName(pg().models.find((m) => m.id === id))} ${ses.loadBefore[id] || 'not run'}`).join('; ') + '.' : ''}</li>
    ${showId ? `<li><b>Settings:</b> ${ses.order.filter((id) => ses.params[id]).map((id) => `${pg().tileName(pg().models.find((m) => m.id === id))}: ${esc(settingsText(pg().models.find((m) => m.id === id), ses.params[id]))}`).join('; ')}.</li>` : ''}
    <li><b>Timing:</b> "Generation time" and RTF measure the model's work only (comparable between models for this sentence); "Its turn → audio" adds any model loading; "You waited" counts from your click, including the models before it. Loading a model the first time is a one-off cost, not a speed of the model.</li>
    <li><b>Length matters:</b> each model decides how long the speech is; RTF divides by that length, so compare RTF rather than raw seconds when lengths differ.</li>
    <li><b>One run each:</b> timings vary between runs, sentences, recordings and computers. This is a single observation, not a ranking. Quality is for your ears: no automatic quality score is computed.</li>
    <li><b>Where:</b> ${esc(ses.env.browser)}${ses.env.webgpu ? ', WebGPU available' : ', no WebGPU (CPU only)'}${ses.env.cores ? `, ${ses.env.cores} CPU threads` : ''}. Everything ran in this tab; nothing was uploaded.</li></ul></details>`;
}

// ---- public -------------------------------------------------------------------------------------------------------------------------
export function mount(root) {
  C.root = root;
  root.innerHTML = `<header class="view-head"><h1 id="cmpTitle" tabindex="-1">Compare models</h1><p class="lede">Same message. Same voice. Different models. Listen side by side.</p></header>
    <section class="cmp-inputs" id="cmpInputs" aria-label="What to compare"><div class="cmp-field" id="cmpMsg"></div><div id="cmpRest"></div></section><section class="cmp-results" id="cmpResults" aria-live="polite"></section>`;
  renderMsg(); render(); renderResults();
  document.addEventListener('pg:busy', () => { if (window.studio?.view === 'compare' && !C.session?.running) render(); });
  store.subscribe(() => { if (window.studio?.view === 'compare' && C.session && !C.session.running) renderResults(); });
}
export function onShow() { if (!C.session?.running) { if (C.text == null) renderMsg(); render(); } }
export function prefill({text, models} = {}) {   // from Create's result ("Compare models") or a creation ("Compare")
  C.text = text ?? null; C.accepted = false; C.picked = new Set(models || []); C.userPicked = false;
  if (C.root && !C.session?.running) { renderMsg(); render(); }
}
export const state = C;
